import random


def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    cc = cd = dc = dd = 0
    for my, op in history:
        if my == 'C':
            if op == 'C':
                cc += 1
            else:
                cd += 1
        else:
            if op == 'C':
                dc += 1
            else:
                dd += 1

    # Detect deterministic exploitation patterns.
    opp_defects = cd + dd
    if n >= 8 and opp_defects == 0:
        return 'C'
    if n >= 6 and cd == 0 and dd == 0:
        return 'C'

    # Punish sustained exploitation, but leave room to re-establish cooperation.
    opp_recent_defects = 0
    tail = min(n, 8)
    for i in range(n - tail, n):
        if history[i][1] == 'D':
            opp_recent_defects += 1

    my_recent_defects = 0
    for i in range(n - tail, n):
        if history[i][0] == 'D':
            my_recent_defects += 1

    # If opponent has been cooperating heavily overall, cooperate.
    if opp_defects * 3 <= n:
        if opp_recent_defects <= 1:
            return 'C'
        if my_recent_defects >= 2 and opp_recent_defects <= 3:
            return 'C'

    # Immediate retaliation to last defect.
    if history[-1][1] == 'D':
        # If we already punished last round, sometimes restore cooperation.
        if history[-1][0] == 'D' and opp_recent_defects <= 2:
            return 'C'
        # Punish unless it's late and mutual defection is costly.
        if dd >= 3 and cd + dc < 2 and n > 80:
            if rng.random() < 0.5:
                return 'C'
        return 'D'

    # Opponent just cooperated; reward unless we're in a clear anti-exploitation phase.
    if history[-1][0] == 'D':
        if dc > dd and dc >= 2:
            return 'D'
        return 'C'

    # Default: cooperate, but occasionally defect if opponent's defect rate is suspicious.
    if n >= 10 and opp_defects * 2 > n:
        if rng.random() < 0.3:
            return 'D'
    return 'C'
